const keys={};let started=false,roundActive=false,roundNum=1,seconds=99,roundTimer=0,enemyThink=0,playerWins=0,enemyWins=0,comboCount=0,shake=0,flashTimer=0,betweenTimer=0;let previous=performance.now();
const healthP=document.querySelector('#p-health'),healthE=document.querySelector('#e-health'),timerEl=document.querySelector('#timer'),comboEl=document.querySelector('#combo'),flashEl=document.querySelector('#flash'),overlay=document.querySelector('#overlay'),resultEl=document.querySelector('#result');
function startGame(){if(started&&roundActive)return;started=true;overlay.classList.add('hidden');resultEl.classList.remove('show');if(roundNum===1&&player.health===100&&enemy.health===100)beginRound();else resetMatch()}
function beginRound(){seconds=99;player.health=100;enemy.health=100;healthP.style.width='100%';healthE.style.width='100%';timerEl.textContent='99';player.root.position.set(-2.2,0,.15);enemy.root.position.set(2.2,0,-.1);player.action='idle';enemy.action='idle';player.stun=enemy.stun=0;player.guard=enemy.guard=false;roundActive=false;flashEl.textContent='ROUND '+roundNum;flashEl.classList.add('show');flashTimer=1.35;betweenTimer=1.5;}
function resetMatch(){roundNum=1;playerWins=enemyWins=0;comboCount=0;comboEl.classList.remove('active');beginRound()}
function hideFlash(){flashEl.classList.remove('show')}
document.querySelector('#start').addEventListener('click',startGame);
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup'].includes(k))e.preventDefault();if(k==='enter'){if(!started)startGame();else if(!roundActive&&betweenTimer<=0){if(playerWins>=2||enemyWins>=2)resetMatch();else beginRound()}}keys[k]=true;if(!e.repeat&&roundActive){if(k==='j')attack(player,'punch');if(k==='k')attack(player,'kick');if(k===' ')jump(player);if(k==='shift')dash(player)}});
addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('.touch-btn').forEach(btn=>{const key=btn.dataset.key;const down=e=>{e.preventDefault();keys[key]=true;if(key==='j')attack(player,'punch');if(key==='k')attack(player,'kick');if(key===' ')jump(player)};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',()=>keys[key]=false);btn.addEventListener('pointerleave',()=>keys[key]=false)});
function attack(f,type){if(!roundActive||f.stun>0||f.action==='ko')return;if(f.action==='punch'||f.action==='kick'||f.action==='dash')return;f.action=type;f.actionTime=0;f.attackHit=false;f.guard=false}
function jump(f){if(!roundActive||f.root.position.y>.03||f.stun>0)return;f.velocity=5.1;f.action='jump';f.actionTime=0}
function dash(f){if(!roundActive||f.stun>0||f.action==='dash')return;f.action='dash';f.actionTime=0;f.root.position.x+=f.facing*.58;f.root.position.x=THREE.MathUtils.clamp(f.root.position.x,-5.5,5.5)}
function hit(attacker,defender,type){if(attacker.attackHit)return;const d=Math.abs(attacker.root.position.x-defender.root.position.x);if(d>1.55||Math.abs(attacker.root.position.y-defender.root.position.y)>.9)return;attacker.attackHit=true;const guarded=defender.guard;const damage=(type==='kick'?17:9)*(guarded?.23:1);defender.health=Math.max(0,defender.health-damage);if(defender.isPlayer)healthP.style.width=defender.health+'%';else healthE.style.width=defender.health+'%';if(!guarded){defender.stun=type==='kick'?.42:.27;defender.action='hit';defender.actionTime=0;defender.root.position.x+=attacker.facing*.17;shake=.2;spawnSparks(defender.root.position.x,1.5,defender.root.position.z,type==='kick'?0xffc45a:0xffffff);if(attacker.isPlayer){if(performance.now()-attacker.lastHit<1250)comboCount++;else comboCount=1;attacker.lastHit=performance.now();comboEl.innerHTML=comboCount+' <small>HIT COMBO</small>';comboEl.classList.add('active')}else{comboEl.classList.remove('active')}}else{spawnSparks(defender.root.position.x,1.4,defender.root.position.z,0x68e8de)}
if(defender.health<=0){defender.action='ko';roundActive=false;betweenTimer=2.8;if(attacker.isPlayer)playerWins++;else enemyWins++;setTimeout(()=>{if(playerWins>=2||enemyWins>=2){const win=playerWins>=2;resultEl.querySelector('strong').textContent=win?'YOU WIN':'YOU LOSE';resultEl.querySelector('span').textContent='PRESS ENTER TO FIGHT AGAIN';resultEl.classList.add('show')}else{roundNum++;document.querySelector('#round').textContent=String(roundNum).padStart(2,'0');beginRound()}},1300)}}
const sparks=[];const sparkGeo=new THREE.SphereGeometry(.045,5,4);function spawnSparks(x,y,z,color){for(let i=0;i<9;i++){const m=new THREE.Mesh(sparkGeo,new THREE.MeshBasicMaterial({color,transparent:true}));m.position.set(x,y,z);scene.add(m);sparks.push({m,v:new THREE.Vector3((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*2),life:.42})}}
function setAnim(f,dt){f.walk+=dt*9;const moving=f.isPlayer?(keys.a||keys.arrowleft||keys.d||keys.arrowright):(Math.abs(f.root.position.x-(player.root.position.x+player.facing*.8))>.85);f.guard=f.isPlayer?!!keys.l:(f.action==='guard');if(f.stun>0)f.stun=Math.max(0,f.stun-dt);
const action=f.action;let punch=0,kick=0,block=0,hitPose=0,walkAmt=moving&&f.root.position.y<.03?1:0;
if(action==='punch'){f.actionTime+=dt;punch=Math.sin(Math.min(1,f.actionTime/.24)*Math.PI)*1.25;if(f.actionTime>.17&&!f.attackHit)hit(f,f===player?enemy:player,'punch');if(f.actionTime>.36)f.action='idle'}
else if(action==='kick'){f.actionTime+=dt;kick=Math.sin(Math.min(1,f.actionTime/.36)*Math.PI)*1.42;if(f.actionTime>.26&&!f.attackHit)hit(f,f===player?enemy:player,'kick');if(f.actionTime>.57)f.action='idle'}
else if(action==='hit'){f.actionTime+=dt;hitPose=Math.max(0,1-f.actionTime/.3);if(f.actionTime>.3)f.action='idle'}
else if(action==='ko'){f.actionTime+=dt;hitPose=1;f.body.rotation.z=THREE.MathUtils.lerp(f.body.rotation.z,-1.15,dt*4);f.body.position.y=THREE.MathUtils.lerp(f.body.position.y,-.35,dt*2)}
else if(action==='dash'){f.actionTime+=dt;if(f.actionTime>.22)f.action='idle'}
else if(action==='jump'){if(f.root.position.y<=0&&f.velocity<0){f.root.position.y=0;f.velocity=0;f.action='idle'} }
else if(f.guard)block=1;
if(action!=='ko'){f.body.rotation.z=THREE.MathUtils.lerp(f.body.rotation.z,action==='dash'?.25:action==='hit'?-.2*hitPose:0,dt*10);f.body.position.y=action==='jump'?0:Math.sin(f.walk*2)*.025*walkAmt}
f.arms.forEach((a,i)=>{const active=a.side===1?1:0;const target=punch>0&&active?punch:0;const guardTarget=block?(.8+(active*.5)):0;const rest=.18+(walkAmt?Math.sin(f.walk+i*Math.PI)*.12:0);a.arm.rotation.z=THREE.MathUtils.lerp(a.arm.rotation.z,rest+target+guardTarget-hitPose*.7,dt*15);a.fore.rotation.z=THREE.MathUtils.lerp(a.fore.rotation.z,target>0?-.2:guardTarget?-.65:-.35,dt*12)});
f.legs.forEach((l,i)=>{const isKick=l.side===1;const target=kick>0&&isKick?kick:0;const stride=walkAmt?Math.sin(f.walk+i*Math.PI)*.42:0;l.leg.rotation.z=THREE.MathUtils.lerp(l.leg.rotation.z,target+stride,dt*13);l.shin.rotation.z=THREE.MathUtils.lerp(l.shin.rotation.z,target>0?-.35:0,dt*12)});
if(action==='jump'){f.root.position.y=Math.max(0,f.root.position.y+f.velocity*dt);f.velocity-=12*dt;f.body.position.y=Math.sin(f.actionTime*8)*.04}
}
function enemyAI(dt){if(!roundActive||enemy.stun>0||enemy.action==='ko')return;enemyThink-=dt;const dist=enemy.root.position.x-player.root.position.x;if(Math.abs(dist)>1.3){enemy.guard=false;const speed=dist>0? -1.05:1.05;enemy.root.position.x+=speed*dt;enemy.root.position.x=THREE.MathUtils.clamp(enemy.root.position.x,-5.5,5.5);enemy.action='idle'}else if(enemyThink<=0){enemyThink=.65+Math.random()*.75;if(Math.random()<.23){enemy.action='guard';enemy.actionTime=0}else attack(enemy,Math.random()<.62?'punch':'kick')}}
// Rain streaks in the neon alley
const rainCount=380,rainPositions=new Float32Array(rainCount*3),rainSpeeds=new Float32Array(rainCount);for(let i=0;i<rainCount;i++){rainPositions[i*3]=(Math.random()-.5)*23;rainPositions[i*3+1]=Math.random()*11;rainPositions[i*3+2]=-1.5-Math.random()*8;rainSpeeds[i]=5+Math.random()*5}const rainGeo=new THREE.BufferGeometry();rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPositions,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:0x9fc9e8,size:.025,transparent:true,opacity:.5}));scene.add(rain);
function update(dt,now){if(flashTimer>0){flashTimer-=dt;if(flashTimer<.25)hideFlash()}if(started&&!roundActive&&betweenTimer>0){betweenTimer-=dt;if(betweenTimer<=0&&player.health>0&&enemy.health>0){roundActive=true;flashEl.textContent='FIGHT!';flashEl.classList.add('show');flashTimer=.75}}
if(roundActive){seconds-=dt;if(seconds<=0){seconds=0;roundActive=false;betweenTimer=2;const winner=player.health>=enemy.health?player:enemy;if(winner===player)playerWins++;else enemyWins++;setTimeout(()=>{if(playerWins>=2||enemyWins>=2){resultEl.querySelector('strong').textContent=playerWins>=2?'YOU WIN':'YOU LOSE';resultEl.querySelector('span').textContent='PRESS ENTER TO FIGHT AGAIN';resultEl.classList.add('show')}else{roundNum++;document.querySelector('#round').textContent=String(roundNum).padStart(2,'0');beginRound()}},1200)}timerEl.textContent=String(Math.ceil(seconds)).padStart(2,'0');
if(player.stun<=0&&player.action!=='ko'){const left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright;let direction=(right?1:0)-(left?1:0);if(player.action==='idle'||player.action==='guard'||player.action==='jump'){if(direction){player.root.position.x+=direction*3.35*dt;player.root.position.x=THREE.MathUtils.clamp(player.root.position.x,-5.4,5.4);if(player.action==='guard')player.action='idle'}player.guard=!!keys.l;if(keys.l&&player.action==='idle')player.action='guard';else if(!keys.l&&player.action==='guard')player.action='idle'}}enemyAI(dt)}
setAnim(player,dt);setAnim(enemy,dt);for(let i=sparks.length-1;i>=0;i--){const s=sparks[i];s.life-=dt;s.v.y-=8*dt;s.m.position.addScaledVector(s.v,dt);s.m.material.opacity=Math.max(0,s.life/.42);if(s.life<=0){scene.remove(s.m);s.m.material.dispose();sparks.splice(i,1)}}const p=rain.geometry.attributes.position;for(let i=0;i<rainCount;i++){let y=p.getY(i)-rainSpeeds[i]*dt;if(y<0)y=10+Math.random()*2;p.setY(i,y);p.setX(i,p.getX(i)-dt*.35)}p.needsUpdate=true;
if(shake>0)shake=Math.max(0,shake-dt);const sx=(Math.random()-.5)*shake,sy=(Math.random()-.5)*shake;camera.position.x=THREE.MathUtils.lerp(camera.position.x,sx,dt*8);camera.position.y=THREE.MathUtils.lerp(camera.position.y,5.2+sy,dt*8);camera.lookAt(0,1.08,0);redLight.intensity=21+Math.sin(now*.002)*2;blueLight.intensity=23+Math.cos(now*.0023)*2;healthP.style.width=player.health+'%';healthE.style.width=enemy.health+'%'}
function frame(now){const dt=Math.min(.04,(now-previous)/1000);previous=now;update(dt,now);renderer.render(scene,camera);requestAnimationFrame(frame)}requestAnimationFrame(frame);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2))});
</script></body></html>

